        obj.timestamp_submit = colB || Utilities.formatDate(new Date(), "Asia/Jakarta", "dd/MM/yyyy HH:mm:ss");
        obj.waktuKejadian = colC || "-";
        obj.alamatKejadian = colD || "-";
        obj.kelurahan_final = String(row[4] || row[5] || "Sananwetan");
