        obj.ras = String(row[12] || "-");
        obj.jkHewan = String(row[13] || "-");
        obj.umurHewan = String(row[14] || "-");
        obj.metodePelihara = String(row[15] || "-");
        obj.kondisiHewan = String(row[16] || "-");
        obj.riwayatVaksin = String(row[17] || "-");
        obj.tanggalVaksin = String(row[18] || "-");
