        if (d.sar && d.sar !== "-") return d.sar;
        var pStr4 = String(d.pertolonganPertama || "");
        return (/\\bSAR\\b/i.test(pStr4) || pStr4.toLowerCase().indexOf("serum anti rabies") !== -1) ? "Ya" : "-";
