            kondisiHewan: kondisiHewan !== "-" ? kondisiHewan : ex.kondisiHewan,
            spesiesHPR: spesiesHPR || ex.spesiesHPR,
            rasHewan: String(fullDataFromSheet.ras || ex.rasHewan || "-"),
